            "name": "pattern_set_cell",
            "arguments": {"pattern": 2, "row": row + r, "channel": 4, "effect": 0, "effect_param": arp_params[i]}
        })

# Counter melody with triangle
counter = [
    (0, 'E-5'), (8, 'D-5'), (16, 'C-5'), (24, 'B-4'),
