            "name": "pattern_set_cell",
            "arguments": {"pattern": 3, "row": row, "channel": 0, "note": "C-5", "instrument": KICK, "volume": 56}
        })

    if row % 4 == 0:
        commands.append({
            "name": "pattern_set_cell",
            "arguments": {"pattern": 3, "row": row, "channel": 1, "note": "C-5", "instrument": HIHAT, "volume": 24}
        })

