    (40, 'B-4'), (44, 'D-5'), (48, 'E-5'), (52, 'G#4'),
    (56, 'A-4'), (60, 'E-4')
]
for row, note in epic_melody:
    commands.append({
        "name": "pattern_set_cell",
        "arguments": {"pattern": 4, "row": row, "channel": 4, "note": note, "instrument": SQUARE, "volume": 52}
    })

# Harmony line
harmony = [
