        })

    if row % 4 == 0 and row < 48:
        commands.append({
            "name": "pattern_set_cell",
            "arguments": {"pattern": 5, "row": row, "channel": 1, "note": "C-5", "instrument": HIHAT, "volume": max(16, 40 - row//2)}
        })

